        "sponsor_message" to mapOf(
            "zh" to "鼠音是一款免费开源的音乐播放器。如果它给你带来了更好的听歌体验，欢迎赞助支持我继续坚持下去。你的每一份赞助，都会成为我修复 Bug、打磨细节、开发新功能的动力。赞助完全自愿，谢谢你！",
            "zh-TW" to "鼠音是一款免費開源的音樂播放器。如果它帶給你更好的聽歌體驗，歡迎贊助支持我繼續堅持下去。你的每一份贊助，都會成為我修復 Bug、打磨細節、開發新功能的動力。贊助完全自願，謝謝你！",
            "zh-HK" to "鼠音是一款免費開源的音樂播放器。如果它帶給你更好的聽歌體驗，歡迎贊助支持我繼續堅持下去。你的每一份贊助，都會成為我修復 Bug、打磨細節、開發新功能的動力。贊助完全自願，謝謝你！",
            "zh-MO" to "鼠音是一款免費開源的音樂播放器。如果它帶給你更好的聽歌體驗，歡迎贊助支持我繼續堅持下去。你的每一份贊助，都會成為我修復 Bug、打磨細節、開發新功能的動力。贊助完全自願，謝謝你！",
            "en" to "ShuYin is a free and open-source music player. If it brings you a better listening experience, feel free to sponsor me so I can keep going. Every contribution becomes my motivation to fix bugs, polish details and develop new features. Donations are completely optional. Thank you for your support!",
            "ja" to "シュウインは無料のオープンソース音楽プレーヤーです。より快適な音楽体験を楽しんでいただけたら、ぜひ応援してください。皆さんからの支援ひとつひとつが、バグ修正やディテールの改善、新機能開発を続ける原動力になります。ご支援は完全に任意です。ありがとうございます！",
            "ko" to "ShuYin은 무료 오픈소스 음악 플레이어입니다. 더 나은 음악 경험을 누리고 계시다면 후원으로 저를 응원해 주세요. 여러분의 후원 하나하나가 버그 수정, 디테일 개선, 새로운 기능 개발을 계속할 원동력이 됩니다. 후원은 완전히 자발적입니다. 감사합니다!",
            "fr" to "ShuYin est un lecteur de musique gratuit et open source. S'il vous offre une meilleure expérience d'écoute, n'hésitez pas à me soutenir pour que je continue. Chaque contribution me motive à corriger les bugs, peaufiner les détails et développer de nouvelles fonctionnalités. Les dons sont entièrement facultatifs. Merci de votre soutien !",
            "de" to "ShuYin ist ein kostenloser Open-Source-Musikplayer. Wenn er dir ein besseres Hörerlebnis bietet, darfst du mich gerne unterstützen, damit ich weitermache. Jeder Beitrag motiviert mich, Fehler zu beheben, Details zu verfeinern und neue Funktionen zu entwickeln. Spenden sind völlig freiwillig. Danke für deine Unterstützung!",
            "es" to "ShuYin es un reproductor de música gratuito y de código abierto. Si te ofrece una mejor experiencia de escucha, no dudes en apoyarme para que siga adelante. Cada contribución me motiva a corregir errores, pulir detalles y desarrollar nuevas funciones. Las donaciones son completamente voluntarias. ¡Gracias por tu apoyo!",
            "ru" to "ShuYin — бесплатный музыкальный проигрыватель с открытым исходным кодом. Если он делает ваше прослушивание лучше, вы можете поддержать меня, чтобы я продолжал работу. Каждый взнос вдохновляет меня исправлять ошибки, оттачивать детали и разрабатывать новые функции. Пожертвования полностью добровольны. Спасибо за поддержку!",
            "pt" to "O ShuYin é um reprodutor de música gratuito e de código aberto. Se ele trouxer uma melhor experiência de escuta, sinta-se à vontade para me apoiar para que eu continue. Cada contribuição me motiva a corrigir bugs, aperfeiçoar detalhes e desenvolver novos recursos. As doações são totalmente opcionais. Obrigado pelo apoio!",
            "it" to "ShuYin è un lettore musicale gratuito e open source. Se ti offre un'esperienza di ascolto migliore, non esitare a sostenermi per farmi andare avanti. Ogni contributo mi motiva a correggere bug, rifinire i dettagli e sviluppare nuove funzionalità. Le donazioni sono completamente facoltative. Grazie per il tuo sostegno!",
            "ar" to "ShuYin هو مشغل موسيقى مجاني ومفتوح المصدر. إذا كان يمنحك تجربة استماع أفضل، فلا تتردد في دعمي لكي أستمر. كل مساهمة تدفعني لإصلاح الأخطاء وتحسين التفاصيل وتطوير ميزات جديدة. التبرعات طوعية تمامًا. شكرًا لدعمك!",
            "hi" to "ShuYin एक निःशुल्क ओपन-सोर्स म्यूज़िक प्लेयर है। यदि यह आपको बेहतर संगीत अनुभव देता है, तो मुझे जारी रखने के लिए समर्थन करें। आपका हर योगदान बग ठीक करने, ब्योरे सुधारने और नई सुविधाएँ विकसित करने की मेरी प्रेरणा बनता है। दान पूरी तरह स्वैच्छिक है। आपके समर्थन के लिए धन्यवाद!",
            "th" to "ShuYin เป็นโปรแกรมเล่นเพลงฟรีและโอเพนซอร์ส หากมันทำให้คุณได้รับประสบการณ์การฟังที่ดีขึ้น ยินดีสนับสนุนฉันให้ทำต่อไป ทุกการสนับสนุนคือแรงบันดาลใจให้ฉันแก้ไขบั๊ก ปรับปรุงรายละเอียด และพัฒนาฟีเจอร์ใหม่ ๆ การบริจาคเป็นไปโดยสมัครใจทั้งหมด ขอบคุณที่สนับสนุน!",
            "vi" to "ShuYin là trình phát nhạc miễn phí và mã nguồn mở. Nếu nó mang lại trải nghiệm nghe nhạc tốt hơn, hãy ủng hộ tôi để tôi tiếp tục phát triển. Mỗi đóng góp đều là động lực để tôi sửa lỗi, tinh chỉnh chi tiết và phát triển tính năng mới. Việc ủng hộ hoàn toàn tự nguyện. Cảm ơn sự ủng hộ của bạn!",
            "in" to "ShuYin adalah pemutar musik gratis dan open source. Jika memberikan pengalaman mendengarkan yang lebih baik, silakan dukung saya agar terus berkembang. Setiap donasi menjadi motivasi saya untuk memperbaiki bug, memoles detail, dan mengembangkan fitur baru. Donasi sepenuhnya bersifat sukarela. Terima kasih atas dukunganmu!",
            "tr" to "ShuYin ücretsiz ve açık kaynaklı bir müzik çalardır. Size daha iyi bir dinleme deneyimi sunuyorsa, devam etmem için beni destekleyebilirsiniz. Her katkı, hataları düzeltmek, detayları cilalamak ve yeni özellikler geliştirmek için motivasyonum olur. Bağışlar tamamen gönüllüdür. Desteğiniz için teşekkürler!",
            "ug" to "ShuYin ھەقسىز ۋە ئوچۇق كودلۇق مۇزىكا قويغۇچ. ئەگەر ئۇ سىزگە تېخىمۇ ياخشى ئاڭلاش تەسىراتى ئاتا قىلسا، مېنى داۋاملاشتۇرۇشقا قوللاڭ. ھەربىر قوللاش خاتالىقلارنى تۈزىتىش، تەپسىلاتلارنى مۇكەممەللەشتۈرۈش ۋە يېڭى ئىقتىدارلارنى ئېچىشىمدىكى ھەرىكەتلەندۈرگۈچ كۈچ. ئىئانە پۈتۈنلەي ئىختىيارىدۇر. قوللىغىنىڭىزگە رەھمەت!",
            "mn" to "ShuYin бол үнэгүй, нээлттэй эх кодтой хөгжмийн тоглуулагч юм. Хэрэв энэ нь танд илүү сайн сонсголын туршлага өгөж байгаа бол намайг үргэлжлүүлэхийн тулд дэмжээрэй. Таны дэмжлэг бүр алдаа засах, дэлгэрэнгүйг сайжруулах, шинэ функц хөгжүүлэх миний хөдөлгөгч хүч болно. Хандив бүрэн сайн дурын юм. Дэмжсэнд баярлалаа!",
            "fa" to "ShuYin یک پخش‌کننده موسیقی رایگان و متن‌باز است. اگر تجربه شنیداری بهتری به شما می‌دهد، برای ادامه کار از من حمایت کنید. هر کمک شما انگیزه‌ای برای رفع اشکال، بهبود جزئیات و توسعه قابلیت‌های جدید است. کمک‌ها کاملاً داوطلبانه است. از حمایت شما سپاسگزارم!",
            "ur" to "ShuYin ایک مفت اور اوپن سورس میوزک پلیئر ہے۔ اگر یہ آپ کو بہتر سننے کا تجربہ دیتا ہے تو مجھے جاری رکھنے کے لیے سپانسر کریں۔ آپ کا ہر تعاون بگز کی اصلاح، تفصیلات کی بہتری اور نئی خصوصیات کی ترقی کے لیے میری ترغیب ہے۔ عطیات مکمل طور پر رضاکارانہ ہیں۔ آپ کے تعاون کا شکریہ!",
            "bn" to "ShuYin একটি বিনামূল্যের ওপেন-সোর্স মিউজিক প্লেয়ার। এটি যদি আপনাকে আরও ভালো শোনার অভিজ্ঞতা দেয়, তাহলে আমাকে চালিয়ে যেতে সহায়তা করুন। আপনার প্রতিটি অবদান বাগ ঠিক করা, বিস্তারিত সংশোধন এবং নতুন ফিচার তৈরি করার আমার অনুপ্রেরণা। অনুদান সম্পূর্ণ স্বেচ্ছাসেবী। আপনার সহায়তার জন্য ধন্যবাদ!",
            "pl" to "ShuYin to darmowy odtwarzacz muzyki open source. Jeśli daje Ci lepsze wrażenia ze słuchania, wesprzyj mnie, żebym kontynuował pracę. Każdy wkład motywuje mnie do naprawiania błędów, dopracowywania szczegółów i tworzenia nowych funkcji. Dotacje są całkowicie dobrowolne. Dziękuję za wsparcie!",
            "uk" to "ShuYin — безкоштовний музичний програвач із відкритим кодом. Якщо він покращує ваш досвід прослуховування, підтримайте мене, щоб я продовжував працювати. Кожен внесок надихає мене виправляти помилки, відшліфовувати деталі та розробляти нові функції. Пожертви повністю добровільні. Дякую за підтримку!",
            "nl" to "ShuYin is een gratis en open-source muziekspeler. Als hij je een betere luisterervaring biedt, steun me dan zodat ik door kan gaan. Elke bijdrage motiveert mij om bugs op te lossen, details te verfijnen en nieuwe functies te ontwikkelen. Donaties zijn volledig vrijwillig. Bedankt voor je steun!",
            "sv" to "ShuYin är en gratis musikspelare med öppen källkod. Om den ger dig en bättre lyssningsupplevelse, stöd mig så att jag kan fortsätta. Varje bidrag motiverar mig att fixa buggar, finslipa detaljer och utveckla nya funktioner. Donationer är helt frivilliga. Tack för ditt stöd!",
            "cs" to "ShuYin je bezplatný hudební přehrávač s otevřeným zdrojovým kódem. Pokud vám přináší lepší poslechový zážitek, podpořte mě, abych mohl pokračovat. Každý příspěvek mě motivuje opravovat chyby, dolaďovat detaily a vyvíjet nové funkce. Dary jsou zcela dobrovolné. Děkuji za podporu!",
            "hu" to "A ShuYin egy ingyenes, nyílt forráskódú zenelejátszó. Ha jobb hallgatási élményt nyújt, támogass, hogy folytathassam. Minden hozzájárulás ösztönöz a hibajavításra, a részletek csiszolására és az új funkciók fejlesztésére. Az adományok teljesen önkéntesek. Köszönöm a támogatásodat!",
            "el" to "Το ShuYin είναι ένας δωρεάν μουσικός αναπαραγωγέας ανοιχτού κώδικα. Αν σου προσφέρει καλύτερη εμπειρία ακρόασης, στηρίξτε με για να συνεχίσω. Κάθε συμβολή με παρακινεί να διορθώνω σφάλματα, να βελτιώνω τις λεπτομέρειες και να αναπτύσσω νέες λειτουργίες. Οι δωρεές είναι εντελώς προαιρετικές. Ευχαριστώ για την υποστήριξη!",
            "ro" to "ShuYin este un player muzical gratuit și open source. Dacă îți oferă o experiență de ascultare mai bună, susține-mă să continui. Fiecare contribuție mă motivează să corectez erori, să rafinez detaliile și să dezvolt funcții noi. Donațiile sunt complet opționale. Mulțumesc pentru susținere!",
            "fi" to "ShuYin on ilmainen avoimen lähdekoodin musiikkisoitin. Jos se tarjoaa sinulle paremman kuuntelukokemuksen, tue minua, jotta voin jatkaa. Jokainen tuki kannustaa minua korjaamaan virheitä, hiomaan yksityiskohtia ja kehittämään uusia ominaisuuksia. Lahjoitukset ovat täysin vapaaehtoisia. Kiitos tuestasi!",
            "da" to "ShuYin er en gratis musikafspiller med åben kildekode. Hvis den giver dig en bedre lytteoplevelse, kan du støtte mig, så jeg kan fortsætte. Hvert bidrag motiverer mig til at rette fejl, finpudse detaljer og udvikle nye funktioner. Donationer er helt frivillige. Tak for din støtte!",
            "nb" to "ShuYin er en gratis musikkspiller med åpen kildekode. Hvis den gir deg en bedre lytteopplevelse, kan du støtte meg slik at jeg kan fortsette. Hvert bidrag motiverer meg til å rette feil, finpusse detaljer og utvikle nye funksjoner. Donasjoner er helt frivillige. Takk for støtten!",
            "ms" to "ShuYin ialah pemain muzik percuma dan sumber terbuka. Jika ia memberikan pengalaman mendengar yang lebih baik, sokong saya untuk terus meneruskan. Setiap sumbangan menjadi motivasi saya untuk membaiki pepijat, memperhalusi butiran dan membangunkan ciri baharu. Sumbangan adalah sepenuhnya sukarela. Terima kasih atas sokongan anda!",
            "tl" to "Ang ShuYin ay isang libre at open-source na music player. Kung nagbibigay ito ng mas magandang karanasan sa pakikinig, suportahan mo ako upang magpatuloy. Bawat kontribusyon ay nagsisilbing inspirasyon ko na ayusin ang mga bug, pagandahin ang mga detalye at bumuo ng mga bagong feature. Ang mga donasyon ay ganap na kusang-loob. Salamat sa suporta mo!",
        ),
