            "ug" to "خەيرلىك ئەتى، كىچىك خامتىر قۇياش نۇرىنى قۇلاق خالتىسىغا سالدى، مۇزىكا بىلەن بۈگۈننى باشلاڭ",
            "mn" to "Өглөөний мэнд, жижиг хэрэм хулгана наранг хацартайгаа хийж авлаа, хөгжим өнөөдрийг сэрээе",
            "fa" to "صبح بخیر، همستر کوچک آفتاب را در گونه‌هایش ذخیره کرده، امروز را با موسیقی بیدار کن",
            "ur" to "صبح بخیر، چھوٹا ہیمسٹر دھوپ اپنے رخساروں میں سمیٹتا ہے، موسیقی سے آج کا دن جگائیں",
            "bn" to "সুপ্রভাত, ছোট্ট হ্যামস্টার রোদ গালে ভরে নিয়েছে, গান দিয়ে আজকের দিনটাকে জাগান",
            "pl" to "Dzień dobry, mały chomik pakuje słońce w policzki, obudź ten dzień muzyką",
            "uk" to "Доброго ранку, маленький хом'ячок ховає сонце у щічках, розбуди цей день музикою",
            "nl" to "Goedemorgen, het kleine hamstertje pakt zonneschijn in zijn wangzakken, wek vandaag met muziek",
            "sv" to "God morgon, den lilla hamstern packar solsken i kindpåsarna, väck dagen med musik",
            "cs" to "Dobré ráno, malý křeček si balí sluníčko do lícních váčků, probuď dnešek hudbou",
