        "greeting_morning_3" to mapOf(
            "zh" to "早上好，像囤粮一样囤几首歌，一天都是好心情",
            "zh-TW" to "早上好，像囤糧一樣囤幾首歌，一天都是好心情",
            "zh-HK" to "早晨，好似囤糧咁囤返幾首歌，成日都心情靚",
            "zh-MO" to "早上好，像囤糧一樣囤幾首歌，一天都是好心情",
