            "ja" to "おはよう、餌を集めるみたいに曲を貯めて、一日中ハッピーに",
            "ko" to "좋은 아침, 먹이를 모으듯 노래를 모아두면 하루 종일 기분이 좋아요",
            "fr" to "Bonjour, stockez des chansons comme un hamster stocke des graines, bonne humeur toute la journée",
