            "ru" to "Доброе утро, запасай песни, как хомяк запасает корм, отличное настроение на весь день",
            "pt" to "Bom dia, guarde músicas como o hamster guarda comida, bom humor o dia todo",
            "it" to "Buongiorno, fai scorta di canzoni come il criceto fa scorta di cibo, buon umore tutto il giorno",
