            "th" to "ดึกแล้ว แฮมสเตอร์กลับรังกันหมดแล้ว ลองเปิดเพลงเบา ๆ สักหน่อย",
            "vi" to "Khuya rồi, hamster cũng đã về tổ, thử nghe nhạc nhẹ nhé",
            "in" to "Sudah malam, hamster pun sudah kembali ke sarang, coba musik yang lembut",
