            "ug" to "كېچە چوڭقۇرلاشتى، خامتىرلارمۇ ئۇۋىغا قايتتى، يېنىك مۇزىكا ئاڭلاپ بېقىڭ",
            "mn" to "Шөнө хожуу болж, хэрэм хулганууд ч үүрэндээ буцлаа, зөөлөн хөгжим сонио",
