            "ur" to "رات گہری ہو گئی، ہیمسٹر بھی آشیانے لوٹ آئے، ہلکی موسیقی آزمائیں",
            "bn" to "গভীর রাত, হ্যামস্টাররাও বাসায় ফিরে গেছে, একটু হালকা গান শোনা যাক",
            "pl" to "Jest późno, nawet chomiki wróciły do gniazda, spróbuj delikatnej muzyki",
            "uk" to "Уже пізно, навіть хом'ячки повернулися у гніздо, спробуй легку музику",
            "nl" to "Het is laat, zelfs de hamsters zijn terug in het nest, probeer zachte muziek",
            "sv" to "Det är sent, även hamstrarna är tillbaka i boet, prova lugn musik",
            "cs" to "Je pozdě, dokonce i křečci se vrátili do hnízda, zkus klidnou hudbu",
